import java.util.*;
class Solution {
    public List<List<Integer>> permute(int[] a){
        List<List<Integer>> out=new ArrayList<>();
        dfs(a,new boolean[a.length],new ArrayList<>(),out);
        return out;
    }
    private void dfs(int[] a,boolean[] used,List<Integer> cur,List<List<Integer>> out){
        if(cur.size()==a.length){out.add(new ArrayList<>(cur));return;}
        for(int i=0;i<a.length;i++)if(!used[i]){
            used[i]=true;cur.add(a[i]);
            dfs(a,used,cur,out);
            cur.remove(cur.size()-1);used[i]=false;
        }
    }
}

